public class Main {

    // 统计每个数字出现的次数
    private static Map<Integer, Integer> countFrequency(List<Integer> arr) {
        Map<Integer, Integer> res = new TreeMap<>(); // 使用 TreeMap 自动排序
        for (int n : arr) {
            res.put(n, res.getOrDefault(n, 0) + 1);
        }
        return res;
    }
​
    // 解析输入的逗号分隔的字符串并返回整数列表
    private static List<Integer> parse(String input) {
        List<Integer> res = new ArrayList<>();
        String[] items = input.split(",");
        for (String item : items) {
            res.add(Integer.parseInt(item.trim())); // 处理可能的空格
        }
        return res;
    }
​
    // 处理两个频次 Map，找出公共元素并按最小频次分类
    private static Map<Integer, Set<Integer>> handle(Map<Integer, Integer> count1, Map<Integer, Integer> count2) {
        Map<Integer, Set<Integer>> res = new TreeMap<>(); // TreeMap 确保按 key (频次) 递增排序
        for (Map.Entry<Integer, Integer> entry : count1.entrySet()) {
            int n = entry.getKey();
            if (count2.containsKey(n)) {
                int minCount = Math.min(entry.getValue(), count2.get(n));
                res.computeIfAbsent(minCount, k -> new TreeSet<>()).add(n); // 使用 TreeSet 确保按值排序
            }
        }
        return res;
    }
​
    // 打印结果
    private static void printResult(Map<Integer, Set<Integer>> resMap) {
        if (resMap.isEmpty()) {
            System.out.println("NULL");
        } else {
            for (Map.Entry<Integer, Set<Integer>> entry : resMap.entrySet()) {
                System.out.print(entry.getKey() + ":");
                System.out.println(String.join(",", 
                    entry.getValue().stream()
                        .map(String::valueOf)
                        .toArray(String[]::new)
                ));
            }
        }
    }
​
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s1 = scanner.nextLine();
        String s2 = scanner.nextLine();
        scanner.close();
​
        List<Integer> ans1 = parse(s1);
        List<Integer> ans2 = parse(s2);
​
        Map<Integer, Integer> count1 = countFrequency(ans1);
        Map<Integer, Integer> count2 = countFrequency(ans2);
​
        Map<Integer, Set<Integer>> res = handle(count1, count2);
        printResult(res);
    }
}
