const readline = require('readline');
​
/**
 * 统计每个数字出现的次数
 * @param {number[]} arr - 需要统计的数组
 * @returns {Map<number, number>} - 统计后的频次 Map
 */
function countFrequency(arr) {
    const freqMap = new Map();
    for (const num of arr) {
        freqMap.set(num, (freqMap.get(num) || 0) + 1);
    }
    return freqMap;
}
​
/**
 * 解析输入的逗号分隔字符串并返回整数数组
 * @param {string} inputStr - 逗号分隔的数字字符串
 * @returns {number[]} - 解析后的整数数组
 */
function parse(inputStr) {
    return inputStr.split(',').map(Number);
}
​
/**
 * 处理两个数组的频次 Map，找出相同的数字并按最小频次分组
 * @param {Map<number, number>} count1 - 第一个数组的频次 Map
 * @param {Map<number, number>} count2 - 第二个数组的频次 Map
 * @returns {Map<number, Set<number>>} - 按最小频次分组的 Map
 */
function handle(count1, count2) {
    const resultMap = new Map();
​
    for (const [num, freq1] of count1) {
        if (count2.has(num)) {
            const minFreq = Math.min(freq1, count2.get(num));
            if (!resultMap.has(minFreq)) {
                resultMap.set(minFreq, new Set());
            }
            resultMap.get(minFreq).add(num);
        }
    }
​
    return new Map([...resultMap.entries()].sort((a, b) => a[0] - b[0])); // 按频次升序排序
}
​
/**
 * 打印最终结果
 * @param {Map<number, Set<number>>} resMap - 结果 Map
 */
function printResult(resMap) {
    if (resMap.size === 0) {
        console.log("NULL");
    } else {
        for (const [count, numbers] of resMap) {
            console.log(`${count}:${[...numbers].sort((a, b) => a - b).join(',')}`);
        }
    }
}
