package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strings"
)
​
func main() {
    // 使用bufio读取输入
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    m := 0
    fmt.Sscan(scanner.Text(), &m)
​
    scanner.Scan()
    n := 0
    fmt.Sscan(scanner.Text(), &n)
​
    scanner.Scan()
    sequence := scanner.Text()
​
    // 芯片消耗映射
    chipCost := map[byte]int{
        'A': 1,
        'B': 2,
        'C': 8,
    }
​
    // 每个处理单元的核数初始化为m
    ans := make([]int, n)
    for i := 0; i < n; i++ {
        ans[i] = m
    }
​
    // 执行每个指令
    for i := 0; i < len(sequence); i++ {
        c := sequence[i]
        cost := chipCost[c]
        // 优先使用前面的处理单元
        for j := 0; j < n; j++ {
            if ans[j] >= cost {
                ans[j] -= cost
                break
            }
        }
    }
​
    // 输出结果
    for i := 0; i < n; i++ {
        // 输出处理单元的状态：1表示使用的核，0表示剩余的核
        fmt.Println(strings.Repeat("1", m-ans[i]) + strings.Repeat("0", ans[i]))
    }
}
